import random, time
def call_with_retry(send, max_tries=5, base=0.5, cap=8):
    for n in range(max_tries):
        try:
            return send(timeout=15)
        except RateLimitOrServerError:
            time.sleep(random.uniform(0, min(cap, base * 2 ** (n + 1))))
    raise RuntimeError('model unavailable')
